UPDATE BOT_LETTER bl
JOIN EXCLUSIVE e ON bl.exclusive_id = e.exclusive_id
SET bl.is_read = TRUE, bl.read_at = NOW()
WHERE bl.letter_id = #{letterId}
  AND e.user_id = #{userId}

mapper.delete:
DELETE bl FROM BOT_LETTER bl
JOIN EXCLUSIVE e ON bl.exclusive_id = e.exclusive_id
WHERE bl.letter_id = #{letterId}
  AND e.user_id = #{userId}

mapper.update:
UPDATE USER_BOT_RELATION ubr
JOIN EXCLUSIVE e ON ubr.exclusive_id = e.exclusive_id
SET ubr.current_exp = ubr.current_exp + #{expGain}
WHERE e.user_id = #{userId}
  AND e.bot_id = COALESCE(
    (
        SELECT e0.bot_id
        FROM EXCLUSIVE e0
        INNER JOIN USER u0 ON u0.user_id = #{userId} AND u0.user_id = e0.user_id
        WHERE e0.bot_id = u0.assigned_bot_id
        LIMIT 1
    ),
    (
        SELECT e1.bot_id
        FROM EXCLUSIVE e1
        WHERE e1.user_id = #{userId}
        ORDER BY e1.exclusive_id ASC
        LIMIT 1
    )
  )

UPDATE USER_BOT_RELATION ubr
JOIN EXCLUSIVE e ON ubr.exclusive_id = e.exclusive_id
SET ubr.current_exp = #{exp}
WHERE e.user_id = #{userId}
  AND e.bot_id = COALESCE(
    (
        SELECT e0.bot_id
        FROM EXCLUSIVE e0
        INNER JOIN USER u0 ON u0.user_id = #{userId} AND u0.user_id = e0.user_id
        WHERE e0.bot_id = u0.assigned_bot_id
        LIMIT 1
    ),
    (
        SELECT e1.bot_id
        FROM EXCLUSIVE e1
        WHERE e1.user_id = #{userId}
        ORDER BY e1.exclusive_id ASC
        LIMIT 1
    )
  )

UPDATE USER_BOT_RELATION ubr
JOIN EXCLUSIVE e ON ubr.exclusive_id = e.exclusive_id
SET ubr.intimacy_id = #{intimacyId}
WHERE e.user_id = #{userId}
  AND e.bot_id = COALESCE(
    (
        SELECT e0.bot_id
        FROM EXCLUSIVE e0
        INNER JOIN USER u0 ON u0.user_id = #{userId} AND u0.user_id = e0.user_id
        WHERE e0.bot_id = u0.assigned_bot_id
        LIMIT 1
    ),
    (
        SELECT e1.bot_id
        FROM EXCLUSIVE e1
        WHERE e1.user_id = #{userId}
        ORDER BY e1.exclusive_id ASC
        LIMIT 1
    )
  )
